<script>
 import {onMount,onDestroy} from 'svelte';
 let {index,code,language='pt'}=$props();
 const config=$derived(JSON.parse(code));
 const copy={
 pt:{label:'SIMULAÇÃO LOCAL',title:['Seu fluxo, em movimento.','Os dados encontrando seu lugar.'],sub:['Acompanhe o que sua regra faz com uma mensagem recebida.','Acompanhe a transformação entre o formulário e o CRM.'],steps:[['Mensagem recebida','Regra aplicada','Ação executada','Conversa atualizada'],['Formulário recebido','Campos mapeados','Registro criado','Sistemas sincronizados']],play:'Continuar',pause:'Pausar',replay:'Repetir simulação',next:'Próxima etapa',wait:'Aguardando o fluxo…',customer:'Cliente de exemplo',business:'loui / atendimento',typing:'Preparando resposta…',reply:'Olá! Recebemos sua mensagem. Nossa equipe vai continuar seu atendimento.',queued:'Conversa encaminhada à equipe. Nenhuma resposta automática enviada.',high:'Prioridade alta',normal:'Prioridade normal',rule:'Sua regra',request:'Mensagem recebida',source:'Formulário do site',destination:'CRM de demonstração',mapped:'Mapeamento aplicado',received:'Nova solicitação',stage:'Etapa',name:'Nome',pending:'Aguardando registro',done:'Simulação concluída',note:'Nada foi enviado ao WhatsApp ou a um CRM real. Você está acompanhando uma simulação no navegador.'},
 en:{label:'LOCAL SIMULATION',title:['Your workflow in motion.','Data finding its place.'],sub:['Follow your rule as it processes an incoming message.','Follow the transformation from website form to CRM.'],steps:[['Message received','Rule applied','Action executed','Conversation updated'],['Form received','Fields mapped','Record created','Systems synchronized']],play:'Continue',pause:'Pause',replay:'Replay simulation',next:'Next step',wait:'Waiting for the workflow…',customer:'Example customer',business:'loui / support',typing:'Preparing reply…',reply:'Hi! We received your message. Our team will continue the conversation.',queued:'Conversation routed to the team. No automatic reply sent.',high:'High priority',normal:'Normal priority',rule:'Your rule',request:'Incoming message',source:'Website form',destination:'Demo CRM',mapped:'Mapping applied',received:'New request',stage:'Stage',name:'Name',pending:'Waiting for record',done:'Simulation complete',note:'Nothing was sent to WhatsApp or a real CRM. This simulation runs in your browser.'},
 es:{label:'SIMULACIÓN LOCAL',title:['Tu flujo en movimiento.','Los datos encontrando su lugar.'],sub:['Observa cómo tu regla procesa un mensaje recibido.','Sigue la transformación del formulario al CRM.'],steps:[['Mensaje recibido','Regla aplicada','Acción ejecutada','Conversación actualizada'],['Formulario recibido','Campos relacionados','Registro creado','Sistemas sincronizados']],play:'Continuar',pause:'Pausar',replay:'Repetir simulación',next:'Siguiente paso',wait:'Esperando el flujo…',customer:'Cliente de ejemplo',business:'loui / atención',typing:'Preparando respuesta…',reply:'¡Hola! Recibimos tu mensaje. Nuestro equipo continuará la conversación.',queued:'Conversación enviada al equipo. Sin respuesta automática.',high:'Prioridad alta',normal:'Prioridad normal',rule:'Tu regla',request:'Mensaje recibido',source:'Formulario del sitio',destination:'CRM de demostración',mapped:'Mapeo aplicado',received:'Nueva solicitud',stage:'Etapa',name:'Nombre',pending:'Esperando registro',done:'Simulación completada',note:'No se envió nada a WhatsApp ni a un CRM real. Esta simulación ocurre en tu navegador.'}
 };
 const c=$derived(copy[language]||copy.pt);
 const source={nome:'Ana Costa',empresa:'Ateliê Horizonte',etapa:'Primeira conversa',origem:'Website'};
 let step=$state(0),playing=$state(false),timer,reduced=false;
 const final=4;
 function schedule(){clearTimeout(timer);if(playing&&step<final)timer=setTimeout(()=>{step++;if(step===final)playing=false;else schedule();},1400);}
 function toggle(){playing=!playing;schedule();}
 function next(){playing=false;clearTimeout(timer);step=Math.min(final,step+1);}
 function replay(){clearTimeout(timer);step=0;playing=!reduced;schedule();}
 onMount(()=>{const media=matchMedia('(prefers-reduced-motion: reduce)');reduced=media.matches;playing=!reduced;schedule();const change=()=>{reduced=media.matches;if(reduced){playing=false;clearTimeout(timer);}};media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});
 onDestroy(()=>clearTimeout(timer));
</script>
<section class="process-simulation" data-step={step}>
 <header class="simulation-heading"><div><span>{c.label}</span><h2>{c.title[index-1]}</h2><p>{c.sub[index-1]}</p></div><div class="simulation-controls">{#if step<final}<button type="button" class="simulation-toggle" aria-pressed={playing} onclick={toggle}>{playing?c.pause:c.play}</button><button type="button" class="simulation-next" onclick={next}>{c.next}</button>{/if}<button type="button" class="simulation-replay" onclick={replay}>{c.replay}</button></div></header>
 <ol class="simulation-timeline">{#each c.steps[index-1] as label,i}<li class:reached={step>i} class:current={step===i+1}><span>{step>i?'✓':String(i+1).padStart(2,'0')}</span>{label}</li>{/each}</ol>
 <div class="simulation-live-status" role="status">{step===0?c.wait:step===final?c.done:c.steps[index-1][step-1]}</div>
 {#if index===1}
  <div class="automation-stage"><section class="chat-preview"><header><span class="chat-avatar">A</span><div><strong>{c.customer}</strong><small>WhatsApp / {c.label.toLowerCase()}</small></div><span class="chat-indicator" aria-hidden="true"></span></header><div class="chat-messages">
   {#if step>=1}<div class="chat-bubble incoming"><small>{c.request}</small><p>{config.request}</p></div>{/if}
   {#if step>=2}<div class="chat-event">{config.priority==='alta'?c.high:c.normal} · {config.action==='responder'?'responder':'organizar'}</div>{/if}
   {#if step===3&&config.action==='responder'}<div class="chat-typing">{c.typing}<span aria-hidden="true">•••</span></div>{/if}
   {#if step>=4&&config.action==='responder'}<div class="chat-bubble outgoing"><small>{c.business}</small><p>{c.reply}</p><span class="chat-checks" aria-hidden="true">✓✓</span></div>{/if}
   {#if step>=3&&config.action==='organizar'}<div class="chat-routing"><span aria-hidden="true">→</span><p>{c.queued}</p></div>{/if}
  </div><div class="chat-composer" aria-hidden="true"><span>{c.business}</span><span>＋</span></div></section>
  <aside class="workflow-monitor"><h3>{c.rule}</h3><pre>{JSON.stringify(config,null,2)}</pre><div class="workflow-node" class:node-active={step>=1}><span>01</span>message.received</div><div class="workflow-connector" class:node-active={step>=2}></div><div class="workflow-node" class:node-active={step>=2}><span>02</span>priority: {config.priority}</div><div class="workflow-connector" class:node-active={step>=3}></div><div class="workflow-node" class:node-active={step>=3}><span>03</span>{config.action==='responder'?'prepare.reply':'route.to.team'}</div><p class="workflow-outcome">{step===4?c.done:c.wait}</p></aside></div>
 {:else}
  <div class="integration-stage"><section class="integration-source" class:received={step>=1}><header><small>01 / INPUT</small><h3>{c.source}</h3></header><div class="source-row"><span>nome</span><strong>{source.nome}</strong></div><div class="source-row"><span>empresa</span><strong>{source.empresa}</strong></div><div class="source-row"><span>etapa</span><strong>{source.etapa}</strong></div><div class="source-row"><span>origem</span><strong>{source.origem}</strong></div><p class="source-event">{step>=1?c.received:c.wait}</p></section>
  <section class="mapping-stage" class:mapped={step>=2}><small>02 / TRANSFORM</small><h3>{c.mapped}</h3><div><code>{config.name}</code><span>→</span><code>name</code></div><div><code>{config.stage}</code><span>→</span><code>stage</code></div><span class="mapping-packet" class:arrived={step>=3} aria-hidden="true">→</span></section>
  <section class="integration-destination"><header><small>03 / OUTPUT</small><h3>{c.destination}</h3></header>{#if step>=3}<article class="crm-record"><div class="crm-avatar">{source[config.name].slice(0,1)}</div><strong>{source[config.name]}</strong><span>{c.name} ← {config.name}</span><div><small>{c.stage}</small><b>{source[config.stage]}</b></div><footer>{step>=4?'✓ '+c.done:c.steps[1][2]}</footer></article>{:else}<div class="crm-placeholder"><span aria-hidden="true">＋</span><p>{c.pending}</p></div>{/if}</section></div>
 {/if}
 <p class="simulation-note">{c.note}</p>
</section>
